mapper.select:
SELECT  FROM `solution` s

WHERE s.deleted_at IS NULL AND s.status = 'PUBLISHED'
  AND 
  AND s.question_type = #{questionType} AND s.question_id = #{questionId}
ORDER BY s.created_at DESC, s.id DESC
LIMIT #{offset}, #{size}

